actions.script:
import java.util.regex.Pattern
import java.util.regex.Matcher

String fileContent = ""
try {
    fileContent = feedFile.getString("UTF-8")
} catch (Exception e) {
    fileContent = new String(feedFile.get())
}

int matched = 0
int unmatched = 0

// For demo purposes, we fallback to the GL_BANK_HDFC account if not found
String glAccountId = "GL_BANK_HDFC"

// 1. Create the GlReconciliation header
String glRecId = ec.entity.sequencedIdPrimary("mantle.ledger.reconciliation.GlReconciliation", null, null)
ec.entity.makeValue("mantle.ledger.reconciliation.GlReconciliation")
    .setAll([glReconciliationId: glRecId, 
             glReconciliationName: "Imported " + feedFormat + " BRS",
             glAccountId: glAccountId,
             reconciledDate: ec.user.nowTimestamp,
             openingBalance: 0.0,
             reconciledBalance: 0.0,
             statusId: "GLREC_CREATED"])
    .create()

List<Map> bankTransactions = []

if (feedFormat == 'MT940') {
    // Standard MT940 extraction: :61:YYMMDD(CR/DR)Amount...
    Pattern p61 = Pattern.compile("^:61:(\\d{6})(\\d{4})?(C|D)(\\d+,\\d+)(.*)\$", Pattern.MULTILINE)
    Matcher m61 = p61.matcher(fileContent)
    while (m61.find()) {
        String dcMark = m61.group(3)
        String amountStr = m61.group(4).replace(',', '.')
        BigDecimal amount = new BigDecimal(amountStr)
        if (dcMark == 'D') amount = amount.negate()

        bankTransactions.add([date: m61.group(1), amount: amount, desc: m61.group(5)])
    }
} else if (feedFormat == 'CSV') {
    // Date,Description,Debit,Credit,Balance
    String[] lines = fileContent.split("\\r?\\n")
    for (int i = 1; i < lines.length; i++) {
        String[] cols = lines[i].split(",")
        if (cols.length >= 4) {
            BigDecimal debit = cols[2] && cols[2].trim() ? new BigDecimal(cols[2].trim()) : BigDecimal.ZERO
            BigDecimal credit = cols[3] && cols[3].trim() ? new BigDecimal(cols[3].trim()) : BigDecimal.ZERO
            BigDecimal amount = credit > 0 ? credit : debit.negate()
            bankTransactions.add([date: cols[0], amount: amount, desc: cols[1]])
        }
    }
} else {
    // API Mock Connector
    bankTransactions.add([date: "2026-06-05", amount: new BigDecimal("100000.00"), desc: "API Sync - HDFC NetBanking"])
}

// 2. Auto-Match Algorithm
for (Map bTrx in bankTransactions) {
    BigDecimal bankAmt = bTrx.amount

    // Fuzzy Match: Find exact amount inside the GL Ledger that has not been reconciled
    def potentialMatches = ec.entity.find("mantle.ledger.transaction.AcctgTransEntry")
        .condition("glAccountId", glAccountId)
        .condition("amount", bankAmt.abs())
        .condition("reconcileStatusId", "AesNotReconciled")
        .list()

    if (potentialMatches) {
        def match = potentialMatches[0]
        ec.entity.makeValue("mantle.ledger.reconciliation.GlReconciliationEntry")
            .setAll([glReconciliationId: glRecId,
                     acctgTransId: match.acctgTransId,
                     acctgTransEntrySeqId: match.acctgTransEntrySeqId,
                     reconciledAmount: bankAmt.abs()])
            .create()

        match.reconcileStatusId = "AesReconciled"
        match.update()
        matched++
    } else {
        unmatched++
    }
}

matchedCount = matched
unmatchedCount = unmatched
glReconciliationId = glRecId

ec.message.addMessage("Bank statement parsed successfully! " + matchedCount + " transactions auto-matched, " + unmatchedCount + " left unmatched.", "success")
